The fidelity formula also applies to sub-normalized states when at least one of the states is normalized. For these states, the purified distance is $P(\rho,\sigma)=\sqrt{1-F(\rho,\sigma)}$.
For a sub-normalized state $\rho_{ER}$, we use the conditional min-entropy
\begin{equation}
 \Hmin(R|E)_\rho
 =-\log\inf\{\Tr\sigma_E:\sigma_E\ge0,\ \rho_{ER}\le\sigma_E\otimes\I_R\}.
\end{equation}
For a normalized state $\rho_{ER}$ and $0\le\delta<1$, the smooth min-entropy is~\cite[Definition~12]{TCR}
\begin{equation}\label{eq:smoothing}
 H_{\min}^{\delta}(R|E)_\rho
 =\sup\bigl\{\Hmin(R|E)_\omega:\omega_{ER}\ge0,\ \Tr\omega_{ER}\le1,\ P(\omega,\rho)\le\delta\bigr\},
\end{equation}
where $\omega_{ER}$ ranges over operators on $E\otimes R$.

\begin{fact}[One-shot quantum achievability {\cite[Proposition~20]{MW}; \cite[Eqs.~(32)--(33)]{TBR}}]\label{fact:oneshot}
Let $\ket\xi_{RA}$ be any unit vector and let $\ket\psi_{RBE}=(\I_R\otimes U)\ket\xi_{RA}$. For $0<\eta<\delta<1$, there exists an entanglement-transmission code with fidelity $F$ and dimension $M$ satisfying\footnote{The restriction $\eta\in(0,\epsilon]$ accompanying
Eqs.~(32)--(33) of \cite{TBR} should read
$\eta\in(0,\sqrt{\epsilon})$, as follows from
\cite[Proposition~20]{MW}, where the smoothing parameter and the
additional error parameter can be chosen independently and their
sum bounds the purified distance. Here $\epsilon=\delta^2$,
so the corresponding range is $0<\eta<\delta$.}
\begin{equation}\label{eq:oneshot}
 F\ge1-\delta^2,\qquad
 \log M\ge H_{\min}^{\delta-\eta}(R|E)_{\psi_{ER}}-4\log\frac1\eta-1.
\end{equation}
\end{fact}

We record two partial-trace bounds and a bound for convex combinations of vectors for later use.

\begin{lemma}[Marginal bounds]\label{lem:test-marginal}
\textup{(i)} Let $S_{BE}\ge0$ and let $K:B\to B'$ satisfy
$K^\dagger K\le\I_B$. Then
\begin{equation}\label{eq:receiver-contraction}
 \Tr_{B'}\!\left[(K\otimes\I_E)S_{BE}(K^\dagger\otimes\I_E)\right]
 \le\Tr_B S_{BE}.
\end{equation}
\textup{(ii)} Let $Q_{BR}\ge0$ and $\rho_{BER}\ge0$, with no normalization assumed. Set
\begin{align}
 \tau_E=\Tr_{BR}(Q^{1/2}\rho Q^{1/2}),\qquad
 c=\op{\Tr_RQ}.
\end{align}
Then
\begin{equation}\label{eq:test-marginal}
 \Tr_B(Q\rho Q)\le c\,\tau_E\otimes\I_R.
\end{equation}

\textup{(iii)} For any vectors $\ket{v_1},\ldots,\ket{v_m}$ and any probability distribution $p_1, \dots, p_m$ we have
\begin{equation}\label{eq:coherent-sum}
 \left(\sum_{j=1}^m p_j \ket{v_j}\right)
 \left(\sum_{j=1}^m p_j\bra{v_j}\right)
 \leq  \sum_{j=1}^m p_j  \ketbra{v_j}{v_j}.
\end{equation}

\end{lemma}
\begin{proof}
For \textup{(i)}, test the difference between the right- and left-hand
sides against any $Z_E\ge0$. By cyclicity of the trace,~\eqref{eq:receiver-contraction} is equivalent to
\begin{align}
 \Tr\!\left[\bigl((\I_B-K^\dagger K)\otimes Z_E\bigr)S_{BE}\right]\ge0,
\end{align}
which holds since both operators in the product are positive. 

For \textup{(ii)}, by linearity in $\rho$, it suffices to prove the claim for
$\rho=\ketbra{\psi}{\psi}$. Define 
\begin{align}
\ket{\chi} = (\tau_E^{-1/2}\otimes \I_{BR}) Q^{1/2}\ket\psi,
\end{align}
where the inverse is taken on the support of \(\tau_E\). Then $\chi_E = \Tr_{BR} \ketbra\chi\chi = \tau_E^{-1/2}\tau_E  \tau_E^{-1/2}\leq \I_E.$
Since the two marginals of a pure operator have the same nonzero eigenvalues, we also have $\chi_{BR}=\Tr_E \ketbra\chi\chi\le \I_{BR}$.
We put \(|v\rangle=Q^{1/2}|\chi\rangle\). Consequently,
\begin{align} 
v_B= \Tr_{RE} \ketbra vv =\operatorname{tr}_R\!\left(Q^{1/2}\chi_{BR}Q^{1/2}\right) \le \operatorname{tr}_RQ \le c\I_B. 
\end{align}
Applying the same observation about pure-state marginals gives $v_{ER} = \Tr_B \ketbra vv\le c\I_{ER}$. Finally,
$$ Q|\psi\rangle=(\tau_E^{1/2}\otimes \I_{BR})|v\rangle, $$
and therefore
\begin{align}
\Tr_B(Q\ketbra\psi\psi Q) = \big(\tau_E^{1/2}\otimes \I_R\big) v_{ER} \big(\tau_E^{1/2}\otimes \I_R\big)\leq c\tau_E\otimes \I_R.
\end{align}







For \textup{(iii)} it suffices to show that for any vector $\ket w$,
\begin{equation}
 \left|\sum_{j=1}^m p_j \langle w|v_j\rangle\right|^2
 \le \sum_{j=1}^mp_j|\langle w|v_j\rangle|^2,
\end{equation}
which holds by the Cauchy--Schwarz inequality.
\end{proof}

Our quantum blowing-up lemma is expressed in terms of the projective tensor norm. For an operator $Z$ on $B\otimes E$, the projective tensor norm induced by the local operator norms is
\begin{equation}\label{eq:projective}
 \pn{Z}=\inf \sum_j\op{X_j}\op{Y_j}.
\end{equation}
Here the infimum is taken over all expressions $Z=\sum_jX_j\otimes Y_j$
where $X_j$ acts on $B$ and $Y_j$ acts on $E$. In finite dimensions, a compactness argument shows that this infimum is attained. 
The projective tensor norm satisfies the triangle inequality and is the largest reasonable cross norm
on the tensor product of the operator spaces equipped with the operator norm~\cite{Ryan2002}.

\begin{lemma}[Dimension bound for the projective tensor norm]\label{lem:projective-dimension}
For every operator $Z$ on $B\otimes E$,
\begin{equation}\label{eq:projective-dimension}
 \pn{Z}\le\min\big\{(\dim B)^2,(\dim E)^2\big\}\,\op{Z}.
\end{equation}
\end{lemma}
\begin{proof}
Fix an orthonormal basis $\{\ket i:\, i=1, \dots, \dim B\}$ of $B$, and expand
\begin{align}
 Z=\sum_{i,j=1}^{\dim B}\ketbra{i}{j}\otimes Z_{ij},\qquad
 Z_{ij}=(\bra i\otimes\I_E)Z(\ket j\otimes\I_E).
\end{align}
We note that $\|(\bra i\otimes\I_E)\|_{\infty} =\|(\ket j\otimes\I_E)\|_{\infty}=1$, so
$\op{Z_{ij}}\le\op Z$. We also have $\op{\ketbra{i}{j}}=1$, so the definition
of the projective tensor norm gives
\begin{align}
 \pn Z\le\sum_{i,j=1}^{\dim B}\op{Z_{ij}}\le (\dim B)^2\op Z.
\end{align}
We similarly have 
$\pn Z\le(\dim E)^2\op Z$, which proves \eqref{eq:projective-dimension}.
\end{proof}

\section{Fully quantum blowing-up lemma}\label{sec:blowingup}
\begin{theorem}[Quantum blowing-up lemma]\label{thm:upgrade} 
Consider an $M$-dimensional code $(\Enc,\Dec)$ with entanglement fidelity $F>0$, and fix $0<\varepsilon<1$. Let $\Pi=UU^\dagger$ be the orthogonal projector onto the image of the channel's Stinespring isometry $U:A\to B\otimes E$. Let ${\widetilde\Pi}$ be an operator approximation of $\Pi$ satisfying, for some $\Gamma>0$,
\begin{equation}\label{eq:threshold}
 {\widetilde\Pi}\,\Pi=\Pi\,{\widetilde\Pi}=\Pi,\qquad
 \pn {\widetilde\Pi}\le\Gamma,\qquad
 \op{{\widetilde\Pi}-\Pi}\le\frac{\varepsilon\sqrt F}{2}.
\end{equation}
Then there is a code with entanglement fidelity at least $1-\varepsilon^2$ and dimension $M'$ satisfying
\begin{equation}\label{eq:upgrade}
 \boxed{\quad\log M'\ge\log M+\log F-2\log\Gamma-4\log\frac2\varepsilon-1.\quad}
\end{equation}
\end{theorem}

\begin{proof}
Pull the maximally entangled projector back through the decoder, and let $\rho_{BER}$ be the encoded state after the Stinespring isometry:
\begin{align}\label{eq:codetest}
 Q_{BR}&=(\Dec^\dagger\otimes\id_R)(\ketbra{\Phi}{\Phi}_{\widehat L R}),\\
 \rho_{BER}&= (U\otimes \I_R)\big((\Enc\otimes \id_R)(\ketbra{\Phi}{\Phi}_{LR})\big) (U^\dagger\otimes\I_R).

\end{align}
The adjoint $\Dec^\dagger$ is completely positive and unital. Hence
\begin{equation}\label{eq:codetestprops}
 0\le Q\le\I_{BR},\qquad
 \Tr_RQ=\Dec^\dagger(\I_{\widehat L}/M)=\I_B/M,\qquad
 \Pi\rho\Pi=\rho,\qquad\Tr(\rho Q)=F.
\end{equation}

Let $\lambda=\op{\Pi Q\Pi}$. Since $\rho$ is obtained by applying the channel isometry $U$ we have $\Pi\rho\Pi=\rho$ and
\begin{equation}\label{eq:lambdaF}
0< F= \Tr(\rho Q) =\Tr(\Pi \rho \Pi Q)=\Tr(\rho\Pi Q\Pi)\le\lambda.
\end{equation}
Let $\ket\psi$ be a normalized eigenvector of $\Pi Q\Pi$ with maximal eigenvalue $\lambda$. Since $\lambda>0$, we have $\Pi\ket\psi=\ket\psi$ and $\Pi Q\ket\psi=\lambda\ket\psi$. Set
\begin{equation}\label{eq:smoothedvector}
 \ket{\widetilde\psi}=\frac{{\widetilde\Pi}Q\ket\psi}{\norm{{\widetilde\Pi}Q\ket\psi}}.
\end{equation}
Since $Q^2\le Q$, we have $\norm{Q\ket\psi}^2 = \bra\psi Q^2\ket \psi \leq \bra \psi Q\ket \psi = \bra \psi \Pi Q\Pi\ket \psi = \lambda$. The identities ${\widetilde\Pi}\,\Pi=\Pi\,{\widetilde\Pi}=\Pi$ give $\Pi(\widetilde \Pi-\Pi)=0$, implying that 
\begin{equation}\label{eq:orthog}
 \norm{{\widetilde\Pi}Q\ket\psi}^2=\norm{\Pi Q\ket\psi}^2+\norm{({\widetilde\Pi}-\Pi)Q\ket\psi}^2=\lambda^2+\norm{({\widetilde\Pi}-\Pi)Q\ket\psi}^2
 \le\lambda^2+\lambda\op{{\widetilde\Pi}-\Pi}^2.
\end{equation}
In particular, $\norm{{\widetilde\Pi}Q\ket\psi}^2\ge\lambda^2>0$, so $\ket{\widetilde\psi}$ is well defined. Moreover, we have
\begin{align}
\braket{ \psi}{\widetilde\psi} = \frac{\bra \psi \widetilde \Pi Q\ket\psi}{\norm{{\widetilde\Pi}Q\ket\psi}} = \frac{\bra \psi  \Pi \widetilde \Pi Q\ket\psi}{\norm{{\widetilde\Pi}Q\ket\psi}} = \frac{\bra \psi  \Pi  Q\ket\psi}{\norm{{\widetilde\Pi}Q\ket\psi}} = \frac{\lambda}{\norm{{\widetilde\Pi}Q\ket\psi}},
\end{align}
 and
\begin{align} \label{eq:phiP}
 P(\ket{\widetilde\psi},\ket\psi)^2 =1-\frac{\lambda^2}{\norm{{\widetilde\Pi}Q\ket\psi}^2}
 \le 1-\frac{\lambda^2}{\lambda^2+\lambda\op{{\widetilde\Pi}-\Pi}^2}  =\frac{\op{{\widetilde\Pi}-\Pi}^2}{\lambda+\op{{\widetilde\Pi}-\Pi}^2}\le\frac{\varepsilon^2}{4},
\end{align}
where the last inequality uses \eqref{eq:threshold} and $F\le\lambda$.

Set
\begin{equation}\label{eq:tau}
 \tau_E=\Tr_{BR}\!\left(Q^{1/2}\ketbra{\psi}{\psi} Q^{1/2}\right),
 \qquad\Tr\tau_E=\lambda.
\end{equation}
Applying Lemma~\ref{lem:test-marginal}\textup{(ii)} to $\ketbra{\psi}{\psi}$ and using
$\Tr_RQ=\I_B/M$ yield
\begin{equation}\label{eq:Qdom}
 \Tr_B(Q\ketbra{\psi}{\psi} Q)\le\frac1M\,\tau_E\otimes\I_R.
\end{equation}

By the definition of the projective tensor norm and compactness in finite dimensions, we can write
\begin{equation}\label{eq:Kdecomposition}
 {\widetilde\Pi}=\Gamma\sum_j p_jX_j\otimes Y_j,\qquad
 p_j\ge0,\quad\sum_jp_j=1,\quad\op{X_j},\op{Y_j}\le1,
\end{equation}
where $X_j$ acts on $B$ and $Y_j$ acts on $E$. Apply Lemma~\ref{lem:test-marginal}\textup{(iii)} with
$\ket{v_j}=(X_j\otimes Y_j\otimes\I_R)Q\ket\psi$, and then use
Lemma~\ref{lem:test-marginal}\textup{(i)} with $K=X_j$ to remove the contraction $X_j$ under the partial trace to obtain
 \begin{align}
 \widetilde\psi_{ER} = \Tr_B\ketbra{\widetilde\psi}{\widetilde\psi} &= \frac{\Gamma^2}{\norm{{\widetilde\Pi}Q\ket\psi}^2}
\Tr_{B}\Bigg(\Big(  \sum_j p_j\ket{v_j}\Big)\Big(  \sum_j p_j\bra{v_j}\Big)\Bigg)\\
 &\le\frac{\Gamma^2}{\norm{{\widetilde\Pi}Q\ket\psi}^2}
 \sum_jp_j(Y_j\otimes\I_R)\Tr_B(Q\ketbra{\psi}{\psi} Q)(Y_j^\dagger\otimes\I_R)\\
 &\le\frac{\Gamma^2}{M\norm{{\widetilde\Pi}Q\ket\psi}^2}
 \Big(\sum_jp_jY_j\tau_EY_j^\dagger\Big)\otimes\I_R, \label{eq:phidom}
 \end{align}
where the last line follows from~\eqref{eq:Qdom}.
The operator in parentheses has trace at most $\lambda$, because $\sum_jp_j=1$, $\Tr\tau_E=\lambda$, and $Y_j^\dagger Y_j\le\I_E$. Thus
\begin{equation}
 \Hmin(R|E)_{\widetilde\psi_{ER}}\ge\log\frac{M\norm{{\widetilde\Pi}Q\ket\psi}^2}{\Gamma^2\lambda}\geq \log\frac{M\lambda^2}{\Gamma^2\lambda}=\log M+\log\lambda-2\log\Gamma.
\end{equation}
Monotonicity of fidelity under partial trace and \eqref{eq:phiP} give $P(\widetilde\psi_{ER},\psi_{ER})\le\varepsilon/2$. Hence $\widetilde\psi_{ER}$ is allowed in the smoothing in \eqref{eq:smoothing}, and
\begin{equation}\label{eq:entropyupgrade}
 H_{\min}^{\varepsilon/2}(R|E)_{\psi_{ER}}
 \ge\log M+\log\lambda-2\log\Gamma\geq \log M+\log F-2\log\Gamma.
\end{equation}
Because $\Pi\ket\psi=\ket\psi$, the input vector
\begin{equation}\label{eq:inputpullback}
 \ket\xi_{AR}=(\I_R\otimes U^\dagger)\ket\psi
\end{equation}
is normalized and produces $\ket\psi$ after applying the channel isometry $U$. Thus $\ket{\xi}_{AR}$ can be used in Fact~\ref{fact:oneshot} with $\delta=\varepsilon$ and $\eta=\varepsilon/2$ to establish~\eqref{eq:upgrade}. If the stated lower bound is negative, the dimension-one code suffices.
\end{proof}

\section{Approximating the tensor-power image projector}\label{sec:approximation}

We now construct the approximating operator $\widetilde \Pi$ required by quantum blowing-up lemma for $n$ uses of $\N$.  The Stinespring image projector of $\N^{\otimes n}$ is $\Pi^{\otimes n}$, acting on $B^nE^n$.

To construct $\widetilde \Pi$, we use a low-degree polynomial approximating the NOR function on the Boolean cube~\cite{Sherstov}. This polynomial is applied to the sum of the local complementary projectors $\I-\Pi_i$ corresponding to the $i$-th use of the channel. Its degree controls both the approximation error and the projective tensor norm. 

\begin{fact}[NOR approximation {\cite[Theorem~4.5]{Sherstov}}]\label{fact:polynomial}
There is a universal constant $c>0$ such that, for any integer $n$ and $D$ satisfying $3\le D\le n$, there is a real polynomial $p_{n,D}$ of degree at most $D$ satisfying
\begin{align}\label{eq:polyinput}
 p_{n,D}(0)=1,\qquad
 \max_{k\in\{1,\ldots,n\}}|p_{n,D}(k)|
 \le2^{-cD^2/n}, \qquad \max_{k\in\{0,\ldots,n\}}|p_{n,D}(k)|\le1.
\end{align}
\end{fact}

\begin{lemma}[Polynomial projector approximation]\label{lem:polynomial}
Let $\Pi$ be an orthogonal projector on $B\otimes E$, and set $\kappa=\min\{(\dim B)^2,(\dim E)^2\}$. For integers $3\le D\le n/2$, there is an operator ${\widetilde\Pi}_D$ satisfying
\begin{align}\label{eq:polyK}
 {\widetilde\Pi}_D\Pi^{\otimes n}=\Pi^{\otimes n}{\widetilde\Pi}_D&=\Pi^{\otimes n},\qquad
 \op{{\widetilde\Pi}_D-\Pi^{\otimes n}}\le2^{-cD^2/n},\\
 \pn{{\widetilde\Pi}_D}&\le\Gamma_{n,D}:=(2\kappa)^D2^{n h(D/n)}.\label{eq:Gamma}
\end{align}
Here $h(\cdot)$ is the binary entropy function, and the projective tensor norm is based on the bipartition $B^n:E^n$.
\end{lemma}

\begin{proof}
Let $\Pi_i$ be the copy of $\Pi$ acting on $B_iE_i$, set $\Delta_i=\I-\Pi_i$, and let $L=\sum_i\Delta_i$. These projections commute, so $L$ has spectrum in $\{0,\ldots,n\}$ and the projector onto the kernel of $L$ is $\Pi^{\otimes n}$. Thus, choosing ${\widetilde\Pi}_D=p_{n,D}(L)$ and applying Fact~\ref{fact:polynomial} give \eqref{eq:polyK}. It remains to prove~\eqref{eq:Gamma}. 

To expand $p_{n,D}(L)$ into terms supported on small subsets of channel
uses, write the polynomial in the binomial basis. Newton's interpolation formula gives
\begin{equation}\label{eq:newton-coefficients}
 p_{n,D}(x)=\sum_{s=0}^D a_s\binom xs,\qquad
 a_s=\sum_{k=0}^s(-1)^{s-k}\binom sk p_{n,D}(k).
\end{equation}

The coefficient $a_s$ is the $s$-th forward difference of $p_{n,D}(x)$ at zero.
Indeed, taking a forward difference, $f(x)\mapsto f(x+1)-f(x)$,
sends $\binom{x}{s}$ to $\binom{x}{s-1}$; taking $s$ differences
and evaluating at zero therefore isolates $a_s$. Expanding these successive
differences gives the formula for $a_s$ in \eqref{eq:newton-coefficients}.
Since $s\le D\le n$, Fact~\ref{fact:polynomial} gives 
$|p_{n,D}(k)|\leq 1$ for every integer $0\leq k\leq n$. Consequently,
\begin{equation}\label{eq:newton-coefficient-bound}
 |a_s|\le\sum_{k=0}^s\binom sk |p_{n,D}(k)|
 \le\sum_{k=0}^s\binom sk=2^s.
\end{equation}

The operators $\Delta_i$ commute and are projections, so they admit a
common eigenbasis with eigenvalues in $\{0,1\}$. On a common eigenvector
with exactly $k$ eigenvalues equal to one, $L$ acts as $k$, while
$\prod_{i\in S}\Delta_i$ acts as $1$ precisely when every index in $S$
is among these $k$ active indices. There are $\binom{k}{s}$ such subsets
of size $s$. Thus
$\binom{L}{s}=\sum_{|S|=s}\prod_{i\in S}\Delta_i$, and
\eqref{eq:newton-coefficients} yields
\begin{equation}\label{eq:newtonK}
 {\widetilde\Pi}_D=p_{n,D}(L)=\sum_{s=0}^D a_s\binom Ls=\sum_{s=0}^D a_s\sum_{\substack{S\subseteq\{1,\ldots,n\}\\|S|=s}}
 \prod_{i\in S}\Delta_i.
\end{equation}
The empty product, corresponding to $s=0$, is the identity.

For $|S|=s$, the operator $\prod_{i\in S}\Delta_i$ is a projection on
$B_SE_S$, tensored with identities on the remaining registers. Its operator
norm is at most one. Applying Lemma~\ref{lem:projective-dimension} on
$B_S:E_S$, whose local dimensions are $(\dim B)^s$ and $(\dim E)^s$,
gives a projective tensor norm of at most $\kappa^s$.
Adjoining the local identities on $B_{S^c}$ and $E_{S^c}$ does not increase
this bound, since these identities have operator norm one.
The triangle inequality, the $\binom ns$ subsets of size $s$, and
\eqref{eq:newton-coefficient-bound} now give
\begin{equation}\label{eq:projective-sum-bound}
 \pn{{\widetilde\Pi}_D}
 \le\sum_{s=0}^D |a_s|\binom ns\kappa^s
 \le\sum_{s=0}^D\binom ns(2\kappa)^s
 \le(2\kappa)^D\sum_{s=0}^D\binom ns,
\end{equation}
where the last inequality uses $2\kappa\ge1$ and $s\le D$.
Put $t=D/n\le1/2$. Then $t^s(1-t)^{n-s}\ge t^D(1-t)^{n-D}=2^{-nh(t)}$ for $s\le D$. The binomial theorem yields
\begin{equation}
 1\ge\sum_{s=0}^D\binom ns t^s(1-t)^{n-s}
 \ge2^{-nh(t)}\sum_{s=0}^D\binom ns.
\end{equation}
Combining the last two bounds proves \eqref{eq:Gamma}.
\end{proof}

\section{Exponential strong converse}\label{sec:strongconverse}
For $n$ uses of $\N$, an entanglement-transmission code consists of channels $\Enc_n:L_n\to A^n$ and $\Dec_n:B^n\to\widehat L_n$, where $\dim L_n=\dim\widehat L_n=\dim R_n=M_n$. The reference $R_n$ is untouched. Its entanglement fidelity $F_n$ is defined by \eqref{eq:codeF}, with $\N$, $\Enc$, and $\Dec$ replaced by $\N^{\otimes n}$, $\Enc_n$, and $\Dec_n$, and with maximally entangled input and target states on $R_nL_n$ and $R_n\widehat L_n$, respectively. Both maps may act jointly across all channel uses; in particular, the encoded inputs may be entangled across the $n$ copies. The rate is $(\log M_n)/n$ qubits per channel use.

The quantum capacity $Q(\N)$ is the supremum of rates $r$ for which a sequence of these codes has $\liminf_{n\to\infty}(\log M_n)/n\ge r$ and $F_n\to1$. We use the following weak converse bound,
which follows from the characterization of quantum capacity in terms of regularized coherent information.

\begin{fact}[Weak converse {\cite[Theorem~5 (converse) and Proposition~7]{Devetak}}]\label{fact:weakconverse}
For every $r_0>Q(\N)$, there are $0<\varepsilon<1$ and an integer $n_0$ such that, for every $n\ge n_0$, any code for $\N^{\otimes n}$ with fidelity at least $1-\varepsilon^2$ has dimension $M'$ satisfying $\log M'\le nr_0$.
\end{fact}

\begin{proof}[Proof of Theorem~\ref{thm:strongconverse}]
The code conversion in Theorem~\ref{thm:upgrade} also applies to the arbitrary
encoded states allowed in Theorem~\ref{thm:strongconverse}. Indeed, its proof uses the initial state only to obtain a normalized
output $\rho$ supported on the Stinespring image with $\Tr(\rho Q)=F$.
For an arbitrary state on $RA^n$ and an $M$-dimensional decoder target, these
properties and $\Tr_RQ=\I_{B^n}/M$ still hold. The same proof therefore produces
an entanglement-transmission code, to which Fact~\ref{fact:weakconverse} applies.

Set $r=Q(\N)+\gamma$. Choose $Q(\N)<r_0<r$, and fix $\varepsilon$ and $n_0$ from Fact~\ref{fact:weakconverse}. Fix a Stinespring isometry $U$ of $\N$ with image projector $\Pi = UU^\dagger$, and set $\kappa=\min\{(\dim B)^2,(\dim E)^2\}$. Choose $0<\theta<1/2$ small enough that $2h(\theta)+2\theta\log(2\kappa)<r-r_0$, and set
\begin{equation}\label{eq:exponentchoice}
 a=\min\left\{\frac{c\theta^2}{4},\ \frac{r-r_0}2-h(\theta)-\theta\log(2\kappa)\right\}>0,
\end{equation}
where $c$ is the constant from Fact~\ref{fact:polynomial}. All these choices are independent of $n$ and of the code.

For sufficiently large $n$, put $D=\lfloor\theta n\rfloor$. Then $3\le D\le n/2$ and $D\ge\theta n/2$. Lemma~\ref{lem:polynomial} gives an operator ${\widetilde\Pi}_D$ satisfying ${\widetilde\Pi}_D\Pi^{\otimes n}=\Pi^{\otimes n}{\widetilde\Pi}_D=\Pi^{\otimes n}$, with
\begin{align}\label{eq:scapprox}
& \op{{\widetilde\Pi}_D-\Pi^{\otimes n}}\le 2^{-cD^2/n}
 \le2^{-nc\theta^2/4}\le2^{-an},\\
& \log\Gamma_{n,D}=n h(D/n)+D\log(2\kappa)
 \le n\bigl[h(\theta)+\theta\log(2\kappa)\bigr].
\end{align}
The last inequality uses the monotonicity of $h(\cdot)$  on $(0,1/2)$.

Suppose a code of dimension $M\ge2^{nr}$ had fidelity $F>2^{-an}$. Increasing $n_0$ so that $2^{-an/2}\le\varepsilon/2$ for all $n\ge n_0$, we obtain
\begin{equation}
 \op{{\widetilde\Pi}_D-\Pi^{\otimes n}}\le2^{-an}
 \le\frac\varepsilon2\,2^{-an/2}<\frac{\varepsilon\sqrt F}{2}.
\end{equation}
Theorem~\ref{thm:upgrade}, applied to the channel $\N^{\otimes n}$, therefore produces a code with fidelity at least $1-\varepsilon^2$ and dimension $M'$ satisfying
\begin{align}
 \log M'&\ge\log M+\log F-2\log\Gamma_{n,D}-4\log\frac2\varepsilon-1\\
 &>n\bigl[r-a-2h(\theta)-2\theta\log(2\kappa)\bigr]-4\log\frac2\varepsilon-1.
\end{align}
By \eqref{eq:exponentchoice}, $r-a-2h(\theta)-2\theta\log(2\kappa)\ge r_0+a$. Increasing $n_0$ once more so that $na>4\log(2/\varepsilon)+1$, we conclude $\log M'>nr_0$, contradicting Fact~\ref{fact:weakconverse}. Hence every such code satisfies $F\le2^{-an}$. Taking $\alpha_\gamma=a/2$ gives $F_n<2^{-\alpha_\gamma n}$ for all sufficiently large $n$, as claimed.
\end{proof}

\section{Conclusion}\label{sec:conclusion}
The strong converse in this work follows from a fully quantum version of the blowing-up strategy. A code whose fidelity is sufficiently large can be converted into a high-fidelity code, with a loss in logarithmic message size controlled by the original fidelity and the projective tensor norm of an approximate channel-image projector. 

The argument separates two ingredients. The one-shot amplification theorem depends only on the accuracy and projective norm of the projector approximation. The memoryless channel structure supplies such an approximation through a low-degree polynomial. At a rate above capacity, a code with fidelity larger than a suitable exponential threshold would therefore yield a high-fidelity code that violates the weak converse. Smooth conditional min-entropy connects the vector construction directly to the coding theorem.

The resulting exponent is not optimized. Sharper polynomial approximations or channel-specific bounds on the projective tensor norm could improve the quantitative tradeoff. The one-shot theorem also applies whenever another channel model admits projector approximations with the same two controls. Understanding when such approximations exist, and whether their projective norm has a more direct operational interpretation in quantum blowing up, are natural directions for further work.

